<template><div class="page"><div class="page-header"><h2>生产工单</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="wo_id" label="工单编号" width="110"/><el-table-column prop="item_cd" label="产品编码" width="100"/><el-table-column prop="plan_qty" label="计划数" width="80"/><el-table-column prop="actual_qty" label="完成数" width="80"/><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="woStatusTag(row.status)" size="small">{{ row.status||'DRAFT' }}</el-tag></template></el-table-column><el-table-column prop="plan_start" label="计划开始" width="100"/><el-table-column prop="plan_end" label="计划完成" width="100"/><el-table-column prop="warehouse_cd" label="目标仓库" width="90"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'工单 — '+(detail?.wo_id||'')" v-model="drawer" width="500px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="工单编号">{{ detail.wo_id }}</el-descriptions-item><el-descriptions-item label="产品编码">{{ detail.item_cd||'-' }}</el-descriptions-item><el-descriptions-item label="计划数">{{ detail.plan_qty||0 }}</el-descriptions-item><el-descriptions-item label="完成数">{{ detail.actual_qty||0 }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="woStatusTag(detail.status)" size="small">{{ detail.status||'DRAFT' }}</el-tag></el-descriptions-item><el-descriptions-item label="优先级">{{ detail.priority||'NORMAL' }}</el-descriptions-item><el-descriptions-item label="计划开始">{{ detail.plan_start||'-' }}</el-descriptions-item><el-descriptions-item label="计划完成">{{ detail.plan_end||'-' }}</el-descriptions-item><el-descriptions-item label="实际开始">{{ detail.actual_start||'-' }}</el-descriptions-item><el-descriptions-item label="实际完成">{{ detail.actual_end||'-' }}</el-descriptions-item><el-descriptions-item label="目标仓库">{{ detail.warehouse_cd||'-' }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchWorkOrders} from '@/api/mes';import type {MesRecord} from '@/api/mes'
const{items,loading,page,perPage,total}=useListPage<MesRecord>(fetchWorkOrders);const{drawer,detail,open}=useDetailDrawer<MesRecord>()
function woStatusTag(s:string){const m:Record<string,string>={DRAFT:'info',RELEASED:'primary',IN_PROGRESS:'warning',COMPLETED:'success',CANCELLED:'danger'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
